<?php $this->assign('title','Editar setor — '.$area->nome); ?>
<div class="page-heading"><h1>Editar setor — <?= h($area->nome) ?></h1><?= $this->Html->link('Voltar a Setores',['action'=>'index'],['class'=>'btn btn-light']) ?></div>
<section class="panel form-panel"><?= $this->Form->create(null) ?><?= $this->Form->control('nome_apresentacao',['label'=>'Nome do setor','value'=>$area->nome,'readonly'=>true,'class'=>'form-control']) ?>
<div class="row g-3 my-2"><div class="col-md-6"><?= $this->Form->control('data_inicio',['type'=>'date','label'=>'Data de início (somente se conferida)','value'=>$configuration['data_inicio'],'class'=>'form-control']) ?></div><div class="col-md-6"><?= $this->Form->control('data_fim',['type'=>'date','label'=>'Data final','required'=>true,'value'=>$configuration['data_fim'],'class'=>'form-control']) ?></div></div>
